def pts_part(label, prompt, pts, solution, extra=""):
    return dict(label=label, max=pts, prompt=prompt, solution=f"<p>{solution}</p>",
                rubric=(f"<p>{extra}</p>" if extra else "") + f"<p>Worth {pts} point{'s' if pts > 1 else ''}.</p>")


