DISPLAY_MIN = 24  # \ce{...} reactions at least this long are shown as display math (they cannot wrap)


def displayify(s):
    """Inline $\\ce{reaction}$ that is long -> $$\\ce{reaction}$$ so it gets its own scrollable line on phones."""
    import re
    def rep(m):
        body = m.group(1)
        before = m.string[max(0, m.start() - 12):m.start()]
        if ("->" in body or "<=>" in body) and len(body) >= DISPLAY_MIN and not re.search(r"Step \\d+: $", before):
            return "$$\\ce{" + body + "}$$"
        return m.group(0)
    return re.sub(r"(?<!\$)\$\\ce\{((?:[^{}]|\{[^{}]*\})*)\}\$(?!\$)", rep, s)


def tidy(mc, stims, fr):
    for q in mc:
        q["prompt"] = displayify(q["prompt"])
    for s in stims.values():
        s["html"] = displayify(s["html"])
    for f in fr:
        f["stem"] = displayify(f["stem"])
        for part in f["parts"]:
            part["prompt"] = displayify(part["prompt"])


